def calculate_interstitial_properties():
    from pymatgen.core import Structure, PeriodicSite, Element, Specie
    from pymatgen.analysis.defects.core import Interstitial
    from pymatgen.analysis.defects.finder import DefectSiteFinder
    from pathlib import Path

    file_path = Path("tool_source_code/pymatgen-analysis-defects/tests/test_files/GaN.vasp")

    try:
        gan_struct = Structure.from_file(file_path)
    except Exception:
        return {prop: None for prop in [
            "oxidation_state", "charge_states", "fractional_coordinates", "supercell_formula",
            "defect_name", "defect_string_representation", "element_changes", "latex_name",
            "defect_fpos_initial", "defect_fpos_modified", "user_defined_charge_states"
        ]}

    inter_fpos = [0, 0, 0.75]
    n_site = PeriodicSite(Specie("N"), inter_fpos, gan_struct.lattice)

    try:
        inter = Interstitial(gan_struct, n_site)
    except Exception:
        return {prop: None for prop in [
            "oxidation_state", "charge_states", "fractional_coordinates", "supercell_formula",
            "defect_name", "defect_string_representation", "element_changes", "latex_name",
            "defect_fpos_initial", "defect_fpos_modified", "user_defined_charge_states"
        ]}

    try:
        oxidation_state = inter.oxi_state
    except Exception:
        oxidation_state = None

    try:
        charge_states = inter.get_charge_states()
    except Exception:
        charge_states = None

    try:
        fractional_coordinates = inter.defect_structure[inter.defect_site_index].frac_coords.tolist()
    except Exception:
        fractional_coordinates = None

    try:
        supercell_formula = inter.defect_structure.composition.formula
    except Exception:
        supercell_formula = None

    try:
        defect_name = inter.name
    except Exception:
        defect_name = None

    try:
        defect_string_representation = str(inter)
    except Exception:
        defect_string_representation = None

    try:
        element_changes = inter.element_changes
    except Exception:
        element_changes = None

    try:
        latex_name = f"${inter.name}$"
    except Exception:
        latex_name = None

    finder = DefectSiteFinder()

    try:
        defect_fpos_initial = finder.get_defect_fpos(inter.defect_structure, gan_struct).tolist()
    except Exception:
        defect_fpos_initial = None

    try:
        modified_site = PeriodicSite(Specie("N"), [0.3, 0.5, 0.9], gan_struct.lattice)
        inter_modified = Interstitial(gan_struct, modified_site)
        defect_fpos_modified = finder.get_defect_fpos(inter_modified.defect_structure, gan_struct).tolist()
    except Exception:
        defect_fpos_modified = None

    try:
        inter2 = Interstitial(gan_struct, n_site, user_charges=[-100, 102])
        user_defined_charge_states = inter2.get_charge_states()
    except Exception:
        user_defined_charge_states = None

    return {
        "oxidation_state": oxidation_state,
        "charge_states": charge_states,
        "fractional_coordinates": fractional_coordinates,
        "supercell_formula": supercell_formula,
        "defect_name": defect_name,
        "defect_string_representation": defect_string_representation,
        "element_changes": element_changes,
        "latex_name": latex_name,
        "defect_fpos_initial": defect_fpos_initial,
        "defect_fpos_modified": defect_fpos_modified,
        "user_defined_charge_states": user_defined_charge_states
    }

