def calculate_material_properties():
    from pymatgen.core import Structure
    from pymatgen.analysis.defects.supercells import get_sc_fromstruct, get_matched_structure_mapping
    from pathlib import Path

    file_path = Path("tool_source_code/pymatgen-analysis-defects/tests/test_files")
    gan_struct = Structure.from_file(file_path / "GaN.vasp")

    properties = {
        "supercell_matrix_shape": None,
        "matched_supercell_matrix_shape": None,
        "supercell_lattice_parameters_consistency": None
    }

    try:
        # Generate supercell using get_sc_fromstruct
        sc_mat = get_sc_fromstruct(gan_struct)
        sc = gan_struct * sc_mat
        properties["supercell_matrix_shape"] = sc_mat.shape
    except Exception:
        properties["supercell_matrix_shape"] = None

    try:
        # Generate supercell using get_matched_structure_mapping
        result = get_matched_structure_mapping(gan_struct, sc)
        if result:
            sc_mat2, _ = result
            sc2 = gan_struct * sc_mat2
            properties["matched_supercell_matrix_shape"] = sc_mat2.shape
        else:
            properties["matched_supercell_matrix_shape"] = None
    except Exception:
        properties["matched_supercell_matrix_shape"] = None

    try:
        # Check lattice parameter consistency
        if properties["supercell_matrix_shape"] and properties["matched_supercell_matrix_shape"]:
            properties["supercell_lattice_parameters_consistency"] = (
                sc.lattice.abc == sc2.lattice.abc
            )
    except Exception:
        properties["supercell_lattice_parameters_consistency"] = None

    return properties
